import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function with ELA features approximating the target values.
    """
    if x.shape != (3,):
        raise ValueError("Input x must be a NumPy array of shape (3,)")

    # Scale and shift inputs to [-pi, pi] for the sinc function
    x_scaled = (x / 5) * np.pi

    # Sinc function with skewness applied to the first dimension
    sinc_val = 1.0
    if x_scaled[0] != 0:
        sinc_val *= np.sin(x_scaled[0] + 0.6) / (x_scaled[0] + 0.6)
    else:
        sinc_val *= 1.0

    if x_scaled[1] != 0:
        sinc_val *= np.sin(x_scaled[1]) / (x_scaled[1])
    else:
        sinc_val *= 1.0

    if x_scaled[2] != 0:
        sinc_val *= np.sin(x_scaled[2]) / (x_scaled[2])
    else:
        sinc_val *= 1.0

    # Quadratic bowl
    quadratic_val = np.sum(x**2) * 0.1

    # Interaction terms with scaling and offsets
    interaction_val = 0.2 * (x[0] * x[1] + x[1] * x[2] + x[0] * x[2]) + 0.1 * np.sum(x)

    # Scaling to adjust the std
    scaling_factor = 0.05

    return scaling_factor * (sinc_val + quadratic_val + interaction_val)

import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function with ELA features approximating the target values.
    """
    if x.shape != (3,):
        raise ValueError("Input x must be a NumPy array of shape (3,)")

    # Sinc function with skewness applied to the first dimension
    sinc_val = 1.0
    for i in range(3):
        xi = x[i] / 5 * np.pi
        if xi != 0:
            if i == 0:
                sinc_val *= np.sin(xi + 0.6) / (xi + 0.6)
            else:
                sinc_val *= np.sin(xi) / xi
        else:
            sinc_val *= 1.0

    # Quadratic bowl
    quadratic_val = np.sum(x**2) * 0.1

    # Interaction terms
    interaction_val = 0.2 * (x[0] * x[1] + x[1] * x[2] + x[0] * x[2])

    return 0.05 * (sinc_val + quadratic_val + interaction_val)

import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function with ELA features approximating the target values.
    """
    if x.shape != (3,):
        raise ValueError("Input x must be a NumPy array of shape (3,)")

    # Skewed exponential term (dominant for skewness)
    exp_term = np.exp(x[0] + 0.5)

    # Cosine terms with scaled coordinates and interaction;
    cos_term = np.cos(x[1] * 0.8) * np.cos(x[2] * 1.2) * (1 + 0.1 * x[0] * x[1])

    # Quadratic bowl with scaling based on inverse L2 norm
    l2_norm = np.sqrt(np.sum(x**2))
    if l2_norm == 0:
        quad_scale = 1.0  # Avoid division by zero
    else:
        quad_scale = 1.0 / (1 + l2_norm)

    quadratic_val = quad_scale * np.sum(x**2)

    return 0.1 * (exp_term + cos_term + quadratic_val)

import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function with ELA features approximating the target values.
    """
    if x.shape != (3,):
        raise ValueError("Input x must be a NumPy array of shape (3,)")

    # Sinc function with skewness applied to the first dimension
    sinc_val = 1.0
    for i in range(3):
        xi = (x[i] + 0.5) / 5 * np.pi  # Shifted and scaled
        if xi != 0:
            if i == 0:
                sinc_val *= np.sin(xi + 0.7) / (xi + 0.7) # Adjust Skew and amplitude
            else:
                sinc_val *= np.sin(xi) / xi
        else:
            sinc_val *= 1.0

    # Exponential modulation of the Sinc Component
    sinc_val *= np.exp(-0.1 * x[0])

    # Quadratic bowl with shifted origin to adjust skew
    quadratic_val = np.sum((x + 0.3)**2) * 0.1

    # Interaction terms with varied scaling
    interaction_val = 0.2 * (x[0] * x[1] + x[1] * x[2] + x[0] * x[2])

    return 0.05 * (sinc_val + quadratic_val + interaction_val)

import numpy as np

def problem(x: np.ndarray) -> float:
    # A 3D function combining a skewed exponential term, a sum of squares, and pairwise interactions to shape a complex fitness landscape.
    return np.exp(x[0] - 0.5 * x[1] + 0.3 * x[2]) + 0.2 * (x[0]**2 + x[1]**2 + x[2]**2) + 0.1 * (x[0] * x[1] - x[1] * x[2])

