import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function with ELA features approximating the target values.
    """
    if x.shape != (3,):
        raise ValueError("Input x must be a NumPy array of shape (3,)")

    # Skewed gaussian term, adjusted mean and var
    gaussian_term = np.exp(-0.5 * ((x[0] - 1) / 2)**2)

    # Cosine terms with scaled coordinates and interaction;
    cos_term = np.cos(x[1] * 0.7) * np.cos(x[2] * 1.3) * (1 + 0.2 * x[0] * x[1])

    # Quadratic bowl with scaling based on exponential of x[0]
    quad_scale = np.exp(-0.1 * x[0]);

    quadratic_val = quad_scale * np.sum(x**2)

    return 0.1 * (gaussian_term + cos_term + quadratic_val)

