import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function with ELA features approximating the target values.
    """
    if x.shape != (3,):
        raise ValueError("Input x must be a NumPy array of shape (3,)")

    x_scaled = (x / 5) * np.pi
    sinc_val = 1.0
    if x_scaled[0] != 0:
        sinc_val *= np.sin(x_scaled[0] + 0.5) / (x_scaled[0] + 0.5)
    else:
        sinc_val *= 1.0
    for i in range(1,3):
        if x_scaled[i] != 0:
            sinc_val *= np.sin(x_scaled[i]) / x_scaled[i]
        else:
            sinc_val *= 1.0

    quadratic_val = np.sum(x**2) * 0.1
    interaction_val = 0.2 * (x[0] * x[1] + x[1] * x[2] + x[0] * x[2])
    skew_factor = np.exp(x[0]) * 0.005

    return 0.03 * (sinc_val + quadratic_val + interaction_val) + skew_factor

